package com.littlemakers.village.nativeapp;

import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;
import org.json.*;import java.util.*;

/** Offline real-time 3D story theater. This renders meshes; it does not pretend to be an MP4. */
public final class StoryTheaterActivity extends Activity {
 VisualPlayMenu menu;ThemeManager theme;WebArt art;SoundEngine sound;OfflineNarrator narrator;NativeStageSurface stage;
 LinearLayout root,body,actions;TextView caption,title;StoryTheaterState state;int story=-1,page;long resetGeneration;
 boolean foreground,motionPaused;String spokenCaption="";GameDatabase db;PlayerWallet wallet;
 int dp(float x){return theme.dp(x);}
 boolean reduced(){return getSharedPreferences("family",0).getBoolean("reduce_motion",false)||android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)==0;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);theme=new ThemeManager(this);art=new WebArt(this);sound=new SoundEngine(this);db=GameDatabase.create(this);wallet=new PlayerWallet(db);narrator=new OfflineNarrator(this,()->{if(!isFinishing())Toast.makeText(this,"An offline English voice is not installed. The caption stays on screen.",Toast.LENGTH_LONG).show();});resetGeneration=getSharedPreferences("family",0).getLong("quest_reset_generation",0);if(Build.VERSION.SDK_INT>=33)Api33.register(this);if(saved!=null){motionPaused=saved.getBoolean("motionPaused",false);page=saved.getInt("page");int id=saved.getInt("story",-1);if(id>=0&&id<art.stories.length()){openStory(id);return;}}int requested=getIntent().getIntExtra("story",-1);if(requested>=0&&requested<art.stories.length())openStory(requested);else library(page);}
 static final class Api33{static void register(StoryTheaterActivity a){a.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,a::back);}}
 TextView text(String value,int size,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(theme.text);t.setTypeface(theme.font(bold));t.setPadding(dp(5),dp(5),dp(5),dp(5));return t;}
 Button button(String label,Runnable run){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(15);b.setTextColor(theme.text);b.setTypeface(theme.font(true));b.setMinHeight(dp(64));b.setPadding(dp(12),dp(8),dp(12),dp(8));b.setBackground(theme.panel(true));b.setOnClickListener(v->{sound.tap();v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);run.run();});GameUi.control(b,theme);return b;}
 void addAction(String name,Runnable run){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(4),0,dp(4));actions.addView(button(name,run),lp);}
 void disposeStage(){if(menu!=null){menu.pause();menu=null;}if(stage!=null){stage.pauseStage();stage=null;}narrator.stop();sound.stop();}
 void shell(String name){disposeStage();theme=new ThemeManager(this);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(theme.background);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();getWindow().getDecorView().setSystemUiVisibility(theme.dark?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(button("‹",this::back),new LinearLayout.LayoutParams(dp(64),dp(64)));bar.getChildAt(0).setContentDescription("Back to story shelf");title=text(name,20,true);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button home=button("⋯",()->{});home.setContentDescription("Story options");home.setOnClickListener(v->{PopupMenu options=new PopupMenu(this,home);if(story>=0)options.getMenu().add("Make scenes by hand").setOnMenuItemClickListener(item->{startActivity(new Intent(this,CreativeActivity.class).putExtra("destination","story-scene").putExtra("story",story));return true;});options.getMenu().add("Story shelf").setOnMenuItemClickListener(item->{library(page);return true;});options.getMenu().add("Return to previous screen").setOnMenuItemClickListener(item->{finish();return true;});options.show();});bar.addView(home,new LinearLayout.LayoutParams(dp(64),dp(64)));root.addView(bar);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(12),dp(8),dp(12),dp(16));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}
 void library(int selectedPage){persist();story=-1;state=null;page=Math.max(0,Math.min((art.stories.length()-1)/9,selectedPage));shell("Story theater");body.addView(text("You move the story",22,true));body.addView(text("Touch the glowing object, help a friend, then choose the ending.",16,false));body.addView(text(art.stories.length()+" playable stories · page "+(page+1),14,false));int first=page*9,count=Math.min(9,art.stories.length()-first);String[]labels=new String[count];int[]models=new int[count];for(int i=0;i<count;i++){JSONObject episode=art.stories.optJSONObject(first+i);labels[i]=episode.optString("title");models[i]=StoryModels.forItem(episode.optJSONArray("steps").optJSONObject(0).optString("item"));}menu=new VisualPlayMenu(this,theme,labels,models,i->openStory(first+i));body.addView(menu,new LinearLayout.LayoutParams(-1,-2));actions=new LinearLayout(this);actions.setOrientation(1);body.addView(actions);if(page>0)addAction("Previous stories",()->library(page-1));if((page+1)*9<art.stories.length())addAction("More stories",()->library(page+1));body.addView(text("Choose a story. Help a friend. Take your time.",14,false));}
 JSONObject episode(){return art.stories.optJSONObject(story);}
 void openStory(int id){persist();if(id<0||id>=art.stories.length())return;story=id;JSONObject ep=episode();state=new StoryTheaterState(ep.optJSONArray("steps").length(),ep.optJSONArray("choices").length());android.content.SharedPreferences p=getSharedPreferences("creative",0);String key="theater-"+id+"-";state.restore(p.getInt(key+"step",p.getInt("story-step-"+id,0)),p.getInt(key+"ending",-1),p.getBoolean(key+"begun",false),p.getBoolean(key+"placed",false));showStory();}
 void showStory(){shell(episode().optString("title"));FrameLayout viewport=new FrameLayout(this);int stageHeight=Math.max(260,Math.min(520,(int)(getResources().getDisplayMetrics().heightPixels/getResources().getDisplayMetrics().density*.52f)));body.addView(viewport,new LinearLayout.LayoutParams(-1,dp(stageHeight)));stage=new NativeStageSurface(this,theme.dark,()->{if(isFinishing()||stage==null)return;caption.setText("The 3D scene could not start on this device. Return to Story Tree to play on the drawing board.");});stage.cinematic(true);stage.pauseShot(motionPaused);stage.setContentDescription("Live three-dimensional story scene");viewport.addView(stage,new FrameLayout.LayoutParams(-1,-1));View touch=new View(this);touch.setContentDescription("Touch the glowing story object to help. The Help button performs the same action.");touch.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);touch.setFocusable(true);touch.setOnClickListener(v->help());touch.setOnTouchListener((v,e)->{if(e.getActionMasked()==android.view.MotionEvent.ACTION_DOWN)return true;if(e.getActionMasked()==android.view.MotionEvent.ACTION_UP){if(stage!=null&&stage.hitStoryTarget(e.getX(),e.getY(),dp(64)))v.performClick();else if(stage!=null)stage.react(e.getX()*640/Math.max(1,v.getWidth()),e.getY()*840/Math.max(1,v.getHeight()));return true;}return true;});viewport.addView(touch,new FrameLayout.LayoutParams(-1,-1));caption=text("",17,false);caption.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(caption);LinearLayout tools=new LinearLayout(this);Button hear=button("Hear scene",this::hear);tools.addView(hear,new LinearLayout.LayoutParams(0,-2,1));Button replay=button("Look again",()->{if(stage!=null){stage.replayShot();}hear();});tools.addView(replay,new LinearLayout.LayoutParams(0,-2,1));Button pause=button(motionPaused?"Resume motion":"Pause motion",()->{});pause.setOnClickListener(v->{motionPaused=!motionPaused;if(stage!=null)stage.pauseShot(motionPaused);pause.setText(motionPaused?"Resume motion":"Pause motion");});tools.addView(pause,new LinearLayout.LayoutParams(0,-2,1));body.addView(tools);actions=new LinearLayout(this);actions.setOrientation(1);body.addView(actions);refresh();if(foreground)stage.resumeStage();}
 void hear(){if(narrator.muted()){Toast.makeText(this,"Sound is off. You can read the caption.",Toast.LENGTH_SHORT).show();return;}narrator.speak(spokenCaption);}
 void begin(){if(state==null)return;state.begun=true;persist();refresh();}
 void help(){if(state==null||!state.help())return;sound.note(state.step);persist();refresh();}
 void next(){if(state==null||!state.next())return;narrator.stop();persist();refresh();}
 void choose(int answer){if(state==null||!state.choose(answer))return;wallet.creativeCompletion("story-"+story);sound.win();persist();refresh();}
 void refresh(){if(state==null||stage==null)return;JSONObject ep=episode();JSONArray steps=ep.optJSONArray("steps");actions.removeAllViews();if(!state.begun){spokenCaption=ep.optString("summary")+" Touch Begin story when you are ready.";caption.setText(spokenCaption);addAction("Begin story",this::begin);}else if(state.step<state.steps){JSONObject step=steps.optJSONObject(state.step);spokenCaption=step.optString(state.placed?"result":"line");caption.setText("Scene "+(state.step+1)+" of "+state.steps+" · "+spokenCaption);if(state.placed)addAction("Next scene",this::next);else addAction("Help · "+step.optString("label"),this::help);}else if(state.ending<0){spokenCaption=ep.optString("question");caption.setText(spokenCaption);JSONArray answers=ep.optJSONArray("choices");for(int i=0;i<answers.length();i++){final int answer=i;addAction(answers.optString(i),()->choose(answer));}}else{spokenCaption=ep.optJSONArray("endings").optString(state.ending);caption.setText(spokenCaption);addAction("Play this story again",()->{state.restart();persist();refresh();});addAction("Choose another ending",()->{state.ending=-1;persist();refresh();});}stage.submit(frame());}
 SceneFrame frame(){JSONObject ep=episode();JSONArray steps=ep.optJSONArray("steps");ArrayList<SceneFrame.Node>nodes=new ArrayList<>();int through=Math.min(state.step,state.steps-1);for(int i=0;i<=through;i++){JSONObject s=steps.optJSONObject(i);float x=(float)s.optDouble("x",50)*6.4f,y=(float)s.optDouble("y",60)*8.4f;boolean waiting=i==state.step&&!state.placed&&state.begun;if(waiting)nodes.add(new SceneFrame.Node(8,x,y,125,125,0,theme.border,0,false));if(i<state.step||state.placed||waiting)nodes.add(SceneFrame.model(x,y,65,StoryModels.forItem(s.optString("item")),new int[]{0xd7ba83,0x7aa98c,0xa397ae}[i%3],true));}String environment=ep.optString("id").equals("bridge")?"bridge":ep.optString("theme","forest");int bg=environment.equals("night")?0xff263547:environment.equals("ocean")?0xff638f98:0xffaac3bf;return new SceneFrame(nodes,bg,840,environment,state.finished(),state.ending,CompanionCast.first(story),state.step*2+(state.placed?1:0));}
 void persist(){if(state==null||story<0)return;String k="theater-"+story+"-";getSharedPreferences("creative",0).edit().putInt(k+"step",state.step).putInt(k+"ending",state.ending).putBoolean(k+"begun",state.begun).putBoolean(k+"placed",state.placed).apply();}
 void back(){if(story>=0)library(page);else finish();}
 @Override public void onBackPressed(){back();}
 @Override protected void onPause(){foreground=false;if(menu!=null)menu.pause();persist();narrator.stop();sound.stop();if(stage!=null)stage.pauseStage();super.onPause();}
 @Override protected void onResume(){super.onResume();foreground=true;long generation=getSharedPreferences("family",0).getLong("quest_reset_generation",0);if(generation!=resetGeneration){resetGeneration=generation;state=null;story=-1;library(0);return;}if(new ThemeManager(this).dark!=theme.dark||(stage!=null&&stage.reducedMotion()!=reduced())){if(story>=0)showStory();else library(page);}if(menu!=null)menu.resume();if(stage!=null)stage.resumeStage();}
 @Override protected void onSaveInstanceState(Bundle b){persist();b.putBoolean("motionPaused",motionPaused);b.putInt("story",story);b.putInt("page",page);super.onSaveInstanceState(b);}
 @Override protected void onDestroy(){disposeStage();narrator.close();art.clear();db.close();super.onDestroy();}
}
